mapper.update:
UPDATE course
SET status = #{status}, version = version + 1
WHERE course_id = #{courseId}

mapper.select:
SELECT * FROM course
AND course_name LIKE CONCAT('%', #{courseName}, '%')
ORDER BY create_time DESC, course_id DESC LIMIT #{offset}, #{limit}

mapper.sql:
WHERE c.audit_status = 1 AND c.status = 1

    AND c.course_name LIKE CONCAT('%', #{courseName}, '%') ESCAPE '!'

AND c.dept_id = #{deptId}
AND c.credits >= #{minCredits}
AND c.credits <= #{maxCredits}
